sample.code:
#include <iostream>
using namespace std;

struct Point {
    int x, y;
};

Point add(Point a, Point b) {
    Point r;
    r.x = a.x + b.x;
    r.y = a.y + b.y;
    return r;
}

int main() {
    Point p = {2, 3};
    Point q = {4, 1};
    Point s = add(p, q);
    cout << "(" << s.x << ", " << s.y << ")" << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

struct Student {
    string name;
    int marks;
};

Student readStudent() {
    Student s;
    cout << "Enter name and marks: ";
    cin >> s.name >> s.marks;
    return s;
}

void print(const Student &s) {
    cout << s.name << " scored " << s.marks << endl;
}

int main() {
    Student a = readStudent();
    Student b = readStudent();
    print(a);
    print(b);
    if (a.marks > b.marks)
        cout << a.name << " is ahead" << endl;
    else
        cout << b.name << " is ahead" << endl;
    return 0;
}

#include <iostream>
using namespace std;

struct Result {
    int total;
    double average;
    char grade;
};

Result evaluate(int m1, int m2, int m3) {
    Result r;
    r.total = m1 + m2 + m3;
    r.average = r.total / 3.0;
    if (r.average >= 85) r.grade = 'A';
    else if (r.average >= 70) r.grade = 'B';
    else if (r.average >= 50) r.grade = 'C';
    else r.grade = 'F';
    return r;
}

int main() {
    Result res = evaluate(80, 75, 90);
    cout << "Total: " << res.total << ", Average: " << res.average
         << ", Grade: " << res.grade << endl;
    return 0;
}

